def get_user_projects(user_id, status=None, is_archived=None, limit=None, cursor=None, sort_by=None, sort_dir=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0028000" if __import__("os").path.isdir("./environment_mix/0028000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _append_log(endpoint, token_id, user_id_for_log, outcome, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "tt_req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "token_id": token_id,
            "user_id": user_id_for_log,
            "status": outcome,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(token_id):
        # 120 requests / 60s per token (or "ambient:none")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = _now() - datetime.timedelta(seconds=60)
        k = token_id or "ambient:none"
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if (r.get("token_id") or "ambient:none") != k:
                continue
            dt = _parse_dt(r.get("created_at"))
            if not isinstance(dt, datetime.datetime):
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _resolve_auth():
        tokens = _load("api_tokens.json")
        users = _load("users.json")
        if not isinstance(tokens, list):
            tokens = []
        if not isinstance(users, list):
            users = []
        now = _now()
        # Find any active+unexpired token whose user is not deleted (auth rule)
        for tok in tokens:
            if not isinstance(tok, dict):
                continue
            if tok.get("provider") != "ticktick":
                continue
            if tok.get("status") != "active":
                continue
            exp = _parse_dt(tok.get("expires_at"))
            if isinstance(exp, datetime.datetime):
                if exp.tzinfo is None:
                    exp = exp.replace(tzinfo=datetime.timezone.utc)
                if not (exp > now):
                    continue
            uid = tok.get("user_id")
            if not isinstance(uid, str):
                continue
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == uid), None)
            if not u:
                continue
            if u.get("status") == "deleted":
                continue
            return tok, u
        return None, None

    # ---- validate inputs (relaxed to match actual datastore ids) ----
    if not isinstance(user_id, str) or not user_id.strip():
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log("get_user_projects", token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_id must be a non-empty string", field="user_id")

    if status is not None and status not in ("active", "archived", "deleted"):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log("get_user_projects", token_id, user_id, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if is_archived is not None and not isinstance(is_archived, bool):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log("get_user_projects", token_id, user_id, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_archived must be boolean", field="is_archived")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log("get_user_projects", token_id, user_id, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log("get_user_projects", token_id, user_id, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    if sort_by is None:
        sort_by = "sort_order"
    if sort_by not in ("sort_order", "created_at", "updated_at", "name"):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log("get_user_projects", token_id, user_id, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")

    if sort_dir is None:
        sort_dir = "asc"
    if sort_dir not in ("asc", "desc"):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log("get_user_projects", token_id, user_id, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort_dir.", field="sort_dir")

    # ---- auth + rate limit ----
    tok, u = _resolve_auth()
    token_id = tok.get("id") if tok else None
    if not tok or not u:
        _append_log("get_user_projects", token_id, user_id, "UNAUTHORIZED", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API token.")
    rl = _rate_limit_check(token_id)
    if rl:
        _append_log("get_user_projects", token_id, user_id, "RATE_LIMIT", "RATE_LIMIT")
        return rl

    # For this server: user-scoped access must match authenticated user
    if u.get("id") != user_id:
        _append_log("get_user_projects", token_id, user_id, "UNAUTHORIZED", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to access the specified user.")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    # Business rule: get_user_projects returns status in ('active','archived') by default
    rows = [p for p in projects if isinstance(p, dict) and p.get("user_id") == user_id and p.get("status") in ("active", "archived")]
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]
    if is_archived is not None:
        rows = [p for p in rows if p.get("is_archived") is is_archived]

    def _sort_key(p):
        v = p.get(sort_by)
        if sort_by in ("created_at", "updated_at"):
            dt = _parse_dt(v)
            if isinstance(dt, datetime.datetime):
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if sort_by == "sort_order":
            try:
                return int(v)
            except Exception:
                return 0
        if sort_by == "name":
            return (v or "").lower()
        return v

    reverse = (sort_dir == "desc")
    rows.sort(key=lambda p: (_sort_key(p), _parse_dt(p.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=reverse)

    start = 0
    if cursor:
        # Cursor is "after_id" (opaque-ish): find index of row with that id and start after it
        for i, p in enumerate(rows):
            if p.get("id") == cursor:
                start = i + 1
                break

    page = rows[start:start + limit]
    next_cursor = page[-1].get("id") if len(page) == limit else None
    res = {
        "projects": page,
        "total": len(rows),
        "limit": limit,
        "has_more": bool(next_cursor),
        "next_cursor": next_cursor,
    }
    _append_log("get_user_projects", token_id, user_id, "OK", None)
    return res

