def get_project_with_data(project_id, include_tasks=None, include_columns=None, task_status=None, task_limit=None, task_cursor=None, task_sort_by=None, task_sort_dir=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0028000" if __import__("os").path.isdir("./environment_mix/0028000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _append_log(token_id, user_id_for_log, outcome, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "tt_req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_project_with_data",
            "token_id": token_id,
            "user_id": user_id_for_log,
            "status": outcome,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(token_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = _now() - datetime.timedelta(seconds=60)
        k = token_id or "ambient:none"
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if (r.get("token_id") or "ambient:none") != k:
                continue
            dt = _parse_dt(r.get("created_at"))
            if not isinstance(dt, datetime.datetime):
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _resolve_auth():
        tokens = _load("api_tokens.json")
        users = _load("users.json")
        if not isinstance(tokens, list):
            tokens = []
        if not isinstance(users, list):
            users = []
        now = _now()
        for tok in tokens:
            if not isinstance(tok, dict):
                continue
            if tok.get("provider") != "ticktick":
                continue
            if tok.get("status") != "active":
                continue
            exp = _parse_dt(tok.get("expires_at"))
            if isinstance(exp, datetime.datetime):
                if exp.tzinfo is None:
                    exp = exp.replace(tzinfo=datetime.timezone.utc)
                if not (exp > now):
                    continue
            uid = tok.get("user_id")
            if not isinstance(uid, str):
                continue
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == uid), None)
            if not u or u.get("status") == "deleted":
                continue
            return tok, u
        return None, None

    # Validate
    if not isinstance(project_id, str) or not project_id.strip():
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string", field="project_id")

    if include_tasks is None:
        include_tasks = False
    if include_columns is None:
        include_columns = False
    if not isinstance(include_tasks, bool):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_tasks must be boolean", field="include_tasks")
    if not isinstance(include_columns, bool):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_columns must be boolean", field="include_columns")

    if task_status is not None and task_status not in ("active", "completed", "deleted"):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid task_status.", field="task_status")

    if task_limit is None:
        task_limit = 50
    if not isinstance(task_limit, int) or task_limit < 1 or task_limit > 500:
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "task_limit out of range", field="task_limit")

    if task_cursor is not None and not isinstance(task_cursor, str):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "task_cursor must be a string", field="task_cursor")

    if task_sort_by is None:
        task_sort_by = "sort_order"
    if task_sort_by not in ("sort_order", "due_at", "start_at", "created_at", "updated_at"):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid task_sort_by.", field="task_sort_by")

    if task_sort_dir is None:
        task_sort_dir = "asc"
    if task_sort_dir not in ("asc", "desc"):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid task_sort_dir.", field="task_sort_dir")

    # Auth + rate
    tok, u = _resolve_auth()
    token_id = tok.get("id") if tok else None
    if not tok or not u:
        _append_log(token_id, None, "UNAUTHORIZED", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API token.")
    rl = _rate_limit_check(token_id)
    if rl:
        _append_log(token_id, u.get("id"), "RATE_LIMIT", "RATE_LIMIT")
        return rl

    projects = _load("projects.json")
    tasks = _load("tasks.json")
    cols = _load("project_columns.json")
    if not isinstance(projects, list):
        projects = []
    if not isinstance(tasks, list):
        tasks = []
    if not isinstance(cols, list):
        cols = []

    prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not prj or prj.get("status") == "deleted":
        _append_log(token_id, u.get("id"), "NOT_FOUND", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.")
    if prj.get("user_id") != u.get("id"):
        _append_log(token_id, u.get("id"), "UNAUTHORIZED", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to access this project.")

    resp = {"project": prj}

    if include_columns:
        resp["columns"] = [c for c in cols if isinstance(c, dict) and c.get("project_id") == project_id and c.get("status") == "active"]

    if include_tasks:
        trows = [t for t in tasks if isinstance(t, dict) and t.get("project_id") == project_id and t.get("status") != "deleted"]
        if task_status is not None:
            # For embedded tasks, allow filtering to include 'deleted' if asked, but default dataset is non-deleted per business rule.
            if task_status == "deleted":
                trows = [t for t in tasks if isinstance(t, dict) and t.get("project_id") == project_id and t.get("status") == "deleted"]
            else:
                trows = [t for t in trows if t.get("status") == task_status]

        def _task_sort_key(t):
            v = t.get(task_sort_by)
            if task_sort_by in ("due_at", "start_at", "created_at", "updated_at"):
                dt = _parse_dt(v)
                if isinstance(dt, datetime.datetime):
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    return dt
                return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if task_sort_by == "sort_order":
                try:
                    return int(v)
                except Exception:
                    return 0
            return v

        reverse = (task_sort_dir == "desc")
        trows.sort(key=lambda t: (_task_sort_key(t), _parse_dt(t.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=reverse)

        start = 0
        if task_cursor:
            for i, t in enumerate(trows):
                if t.get("id") == task_cursor:
                    start = i + 1
                    break
        page = trows[start:start + task_limit]
        next_cursor = page[-1].get("id") if len(page) == task_limit else None
        resp["tasks"] = {
            "tasks": page,
            "total": len(trows),
            "limit": task_limit,
            "has_more": bool(next_cursor),
            "next_cursor": next_cursor,
        }

    _append_log(token_id, u.get("id"), "OK", None)
    return resp

def create_project(user_id, name, color=None, view_mode=None, sort_order=None, is_archived=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0028000" if __import__("os").path.isdir("./environment_mix/0028000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(token_id, user_id_for_log, outcome, error_code=None):
        logs = _load_logs()
        logs.append({
            "id": "tt_req_" + _now().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "create_project",
            "token_id": token_id,
            "user_id": user_id_for_log,
            "status": outcome,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(token_id, user_id_for_rl):
        # Conservative limits: 120/min per token; 600/min and 20k/day per user.
        logs = _load_logs()
        now = _now()
        minute_cutoff = now - datetime.timedelta(seconds=60)
        day_cutoff = now - datetime.timedelta(days=1)
        token_min = user_min = user_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("created_at"))
            if not isinstance(ts, datetime.datetime):
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= minute_cutoff:
                if token_id is not None and r.get("token_id") == token_id:
                    token_min += 1
                if user_id_for_rl is not None and r.get("user_id") == user_id_for_rl:
                    user_min += 1
            if ts >= day_cutoff and user_id_for_rl is not None and r.get("user_id") == user_id_for_rl:
                user_day += 1
        if token_id is not None and token_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for token (120/min).")
        if user_id_for_rl is not None and user_min >= 600:
            return _err("RATE_LIMIT", "Rate limit exceeded for user (600/min).")
        if user_id_for_rl is not None and user_day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for user (20k/day).")
        return None

    def _resolve_auth_user():
        # Ambient auth: pick any active, unexpired token whose user is active (not deleted/disabled).
        tokens = _load("api_tokens.json")
        users = _load("users.json")
        if not isinstance(tokens, list):
            tokens = []
        if not isinstance(users, list):
            users = []
        users_by_id = {u.get("id"): u for u in users if isinstance(u, dict)}
        now = _now()
        for t in tokens:
            if not isinstance(t, dict):
                continue
            if t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at")) if t.get("expires_at") else None
            if isinstance(exp, datetime.datetime):
                if exp.tzinfo is None:
                    exp = exp.replace(tzinfo=datetime.timezone.utc)
                if exp <= now:
                    continue
            u = users_by_id.get(t.get("user_id"))
            if not isinstance(u, dict):
                continue
            if u.get("status") != "active":
                continue
            return t, u
        return None, None

    # Validate inputs
    if not isinstance(user_id, str) or not user_id:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_id must be a non-empty string", field="user_id")
    if not isinstance(name, str) or len(name.strip()) < 1:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")

    if color is not None and not isinstance(color, str):
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "color must be a string", field="color")
    if view_mode is not None:
        if not isinstance(view_mode, str) or view_mode not in ("list", "kanban"):
            token, u = _resolve_auth_user()
            _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "view_mode must be one of: list, kanban", field="view_mode")
    if sort_order is not None:
        if not isinstance(sort_order, int):
            token, u = _resolve_auth_user()
            _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort_order must be an integer", field="sort_order")
        if sort_order < 0:
            token, u = _resolve_auth_user()
            _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort_order must be >= 0", field="sort_order")
    if is_archived is not None and not isinstance(is_archived, bool):
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_archived must be a boolean", field="is_archived")

    token, auth_user = _resolve_auth_user()
    if not token or not auth_user:
        _append_log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API token is missing/invalid.")

    rl_err = _rate_limit_check(token.get("id"), auth_user.get("id"))
    if rl_err:
        _append_log(token.get("id"), auth_user.get("id"), "error", rl_err["error"]["code"])
        return rl_err

    # Enforce that caller can only create for themselves; BUT to avoid false UNAUTHORIZED,
    # we accept the request only when user_id matches the resolved auth user id.
    if user_id != auth_user.get("id"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to create projects for the specified user.", rule="projects.user_id must equal current_user.id")

    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    target_user = next((u for u in users if isinstance(u, dict) and u.get("id") == user_id), None)
    if not target_user:
        _append_log(token.get("id"), auth_user.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "User not found.", resource="users", id=user_id)
    if target_user.get("status") != "active":
        _append_log(token.get("id"), auth_user.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "User is not active.", rule="status != 'deleted' required for authentication/authorization")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    # Quota: <= 500 active projects
    active_count = 0
    for p in projects:
        if isinstance(p, dict) and p.get("user_id") == user_id and p.get("status") == "active":
            active_count += 1
    if active_count >= 500:
        _append_log(token.get("id"), auth_user.get("id"), "error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Project limit exceeded (max 500 active projects).", rule="at most 500 active projects")

    nm = name.strip()
    for p in projects:
        if not isinstance(p, dict):
            continue
        if p.get("user_id") == user_id and p.get("status") != "deleted" and (p.get("name") or "").strip() == nm:
            _append_log(token.get("id"), auth_user.get("id"), "error", "CONFLICT")
            return _err("CONFLICT", "Project name must be unique per user among non-deleted projects.", rule="unique(user_id, name) where status != 'deleted'", field="name")

    # Defaults
    vm = view_mode if view_mode is not None else "list"
    ia = bool(is_archived) if is_archived is not None else False
    status_val = "archived" if ia else "active"

    if sort_order is None:
        # place at end deterministically
        max_sort = -1
        for p in projects:
            if isinstance(p, dict) and p.get("user_id") == user_id and p.get("status") != "deleted":
                so = p.get("sort_order")
                if isinstance(so, int) and so > max_sort:
                    max_sort = so
        sort_order_val = max_sort + 1
    else:
        sort_order_val = sort_order

    now = _iso(_now())
    new_id = "tt_prj_" + secrets.token_hex(9).upper()
    rec = {
        "id": new_id,
        "user_id": user_id,
        "name": nm,
        "color": color,
        "view_mode": vm,
        "sort_order": sort_order_val,
        "is_archived": ia,
        "status": status_val,
        "created_at": now,
        "updated_at": now,
        "deleted_at": None
    }

    # Constraint: is_archived=true implies status='archived' OR status='deleted'
    if rec["is_archived"] and rec["status"] not in ("archived", "deleted"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_archived=true requires status='archived' (or 'deleted').", rule="is_archived = true implies status = 'archived' OR status='deleted'")

    projects.append(rec)
    _save("projects.json", projects)

    # Update token last_used_at
    tokens = _load("api_tokens.json")
    if isinstance(tokens, list):
        changed = False
        for t in tokens:
            if isinstance(t, dict) and t.get("id") == token.get("id"):
                t["last_used_at"] = now
                t["updated_at"] = now if isinstance(t.get("updated_at"), str) else t.get("updated_at", now)
                changed = True
                break
        if changed:
            _save("api_tokens.json", tokens)

    _append_log(token.get("id"), auth_user.get("id"), "success", None)
    return {"project": rec}

def update_project(project_id, name=None, color=None, view_mode=None, sort_order=None, is_archived=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0028000" if __import__("os").path.isdir("./environment_mix/0028000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _append_log(token_id, user_id_for_log, outcome, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "tt_req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "update_project",
            "token_id": token_id,
            "user_id": user_id_for_log,
            "status": outcome,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(token_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = _now() - datetime.timedelta(seconds=60)
        k = token_id or "ambient:none"
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if (r.get("token_id") or "ambient:none") != k:
                continue
            dt = _parse_dt(r.get("created_at"))
            if not isinstance(dt, datetime.datetime):
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _resolve_auth():
        tokens = _load("api_tokens.json")
        users = _load("users.json")
        if not isinstance(tokens, list):
            tokens = []
        if not isinstance(users, list):
            users = []
        now = _now()
        for tok in tokens:
            if not isinstance(tok, dict):
                continue
            if tok.get("provider") != "ticktick":
                continue
            if tok.get("status") != "active":
                continue
            exp = _parse_dt(tok.get("expires_at"))
            if isinstance(exp, datetime.datetime):
                if exp.tzinfo is None:
                    exp = exp.replace(tzinfo=datetime.timezone.utc)
                if not (exp > now):
                    continue
            uid = tok.get("user_id")
            if not isinstance(uid, str):
                continue
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == uid), None)
            if not u or u.get("status") == "deleted":
                continue
            return tok, u
        return None, None

    if not isinstance(project_id, str) or not project_id.strip():
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string", field="project_id")

    if name is not None and (not isinstance(name, str) or not name.strip()):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
    if color is not None and not isinstance(color, str):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "color must be a string", field="color")
    if view_mode is not None and view_mode not in ("list", "kanban"):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid view_mode.", field="view_mode")
    if sort_order is not None and (not isinstance(sort_order, int) or sort_order < 0):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_order must be an integer >= 0", field="sort_order")
    if is_archived is not None and not isinstance(is_archived, bool):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_archived must be boolean", field="is_archived")
    if status is not None and status not in ("active", "archived", "deleted"):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    tok, u = _resolve_auth()
    token_id = tok.get("id") if tok else None
    if not tok or not u:
        _append_log(token_id, None, "UNAUTHORIZED", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API token.")
    rl = _rate_limit_check(token_id)
    if rl:
        _append_log(token_id, u.get("id"), "RATE_LIMIT", "RATE_LIMIT")
        return rl

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    idx = next((i for i, p in enumerate(projects) if isinstance(p, dict) and p.get("id") == project_id), None)
    if idx is None:
        _append_log(token_id, u.get("id"), "NOT_FOUND", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.")
    prj = projects[idx]
    if prj.get("user_id") != u.get("id"):
        _append_log(token_id, u.get("id"), "UNAUTHORIZED", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to modify this project.")
    if prj.get("status") == "deleted":
        _append_log(token_id, u.get("id"), "NOT_FOUND", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.")

    # Apply updates with business rules
    now = _now()
    new_prj = dict(prj)

    if name is not None:
        # uniqueness among non-deleted
        for p in projects:
            if not isinstance(p, dict):
                continue
            if p.get("id") == project_id:
                continue
            if p.get("user_id") == prj.get("user_id") and p.get("status") != "deleted" and (p.get("name") or "").strip() == name.strip():
                _append_log(token_id, u.get("id"), "CONFLICT", "CONFLICT")
                return _err("CONFLICT", "A non-deleted project with this name already exists.")
        new_prj["name"] = name.strip()
    if color is not None:
        new_prj["color"] = color
    if view_mode is not None:
        new_prj["view_mode"] = view_mode
    if sort_order is not None:
        new_prj["sort_order"] = sort_order

    # Status + is_archived interactions
    # is_archived=true forces status='archived'; is_archived=false forces status='active' unless already deleted.
    if is_archived is not None:
        new_prj["is_archived"] = bool(is_archived)
        if bool(is_archived):
            desired_status = "archived"
        else:
            desired_status = "active"
        # transition check
        cur = prj.get("status")
        if cur != "deleted" and desired_status != cur:
            allowed = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
            if desired_status not in allowed.get(cur, set()):
                _append_log(token_id, u.get("id"), "INVALID_TRANSITION", "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", f"Cannot transition project status from '{cur}' to '{desired_status}'.")
            new_prj["status"] = desired_status

    if status is not None:
        cur = prj.get("status")
        if status != cur:
            allowed = {"active": {"archived", "deleted"}, "archived": {"active", "deleted"}, "deleted": set()}
            if status not in allowed.get(cur, set()):
                _append_log(token_id, u.get("id"), "INVALID_TRANSITION", "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", f"Cannot transition project status from '{cur}' to '{status}'.")
            new_prj["status"] = status
        # Keep is_archived consistent if status set explicitly
        if new_prj.get("status") == "archived":
            new_prj["is_archived"] = True
        elif new_prj.get("status") == "active":
            new_prj["is_archived"] = False
        elif new_prj.get("status") == "deleted":
            new_prj["is_archived"] = True if new_prj.get("is_archived") else new_prj.get("is_archived", False)

    # deleted_at iff status deleted
    if new_prj.get("status") == "deleted":
        if not new_prj.get("deleted_at"):
            new_prj["deleted_at"] = _iso(now)
    else:
        new_prj["deleted_at"] = None

    # is_archived implies status archived or deleted
    if new_prj.get("is_archived") and new_prj.get("status") not in ("archived", "deleted"):
        new_prj["status"] = "archived"

    new_prj["updated_at"] = _iso(now)
    projects[idx] = new_prj
    _save("projects.json", projects)

    # Update token last_used_at
    tokens = _load("api_tokens.json")
    if isinstance(tokens, list):
        for t in tokens:
            if isinstance(t, dict) and t.get("id") == token_id:
                t["last_used_at"] = _iso(now)
                t["updated_at"] = t.get("updated_at") or _iso(now)
                break
        _save("api_tokens.json", tokens)

    _append_log(token_id, u.get("id"), "OK", None)
    return {"project": new_prj}

