        k = token_id or "ambient:none"
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if (r.get("token_id") or "ambient:none") != k:
                continue
            dt = _parse_dt(r.get("created_at"))
            if not isinstance(dt, datetime.datetime):
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    def _resolve_auth():
        tokens = _load("api_tokens.json")
        users = _load("users.json")
        if not isinstance(tokens, list):
            tokens = []
        if not isinstance(users, list):
            users = []
        now = _now()
        for tok in tokens:
            if not isinstance(tok, dict):
                continue
            if tok.get("provider") != "ticktick":
                continue
            if tok.get("status") != "active":
                continue
            exp = _parse_dt(tok.get("expires_at"))
            if isinstance(exp, datetime.datetime):
                if exp.tzinfo is None:
                    exp = exp.replace(tzinfo=datetime.timezone.utc)
                if not (exp > now):
                    continue
            uid = tok.get("user_id")
            if not isinstance(uid, str):
                continue
            u = next((x for x in users if isinstance(x, dict) and x.get("id") == uid), None)
            if not u or u.get("status") == "deleted":
                continue
            return tok, u
        return None, None

    if not isinstance(project_id, str) or not project_id.strip():
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string", field="project_id")
    if hard_delete is not None and not isinstance(hard_delete, bool):
        tok, u = _resolve_auth()
        token_id = tok.get("id") if tok else None
        _append_log(token_id, None, "VALIDATION_ERROR", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "hard_delete must be boolean", field="hard_delete")

    tok, u = _resolve_auth()
    token_id = tok.get("id") if tok else None
    if not tok or not u:
        _append_log(token_id, None, "UNAUTHORIZED", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid API token.")
    rl = _rate_limit_check(token_id)
    if rl:
        _append_log(token_id, u.get("id"), "RATE_LIMIT", "RATE_LIMIT")
        return rl

    projects = _load("projects.json")
    cols = _load("project_columns.json")
    tasks = _load("tasks.json")
    if not isinstance(projects, list):
        projects = []
    if not isinstance(cols, list):
        cols = []
    if not isinstance(tasks, list):
        tasks = []

    idx = next((i for i, p in enumerate(projects) if isinstance(p, dict) and p.get("id") == project_id), None)
    if idx is None:
        _append_log(token_id, u.get("id"), "NOT_FOUND", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.")
    prj = projects[idx]
    if prj.get("user_id") != u.get("id"):
        _append_log(token_id, u.get("id"), "UNAUTHORIZED", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to delete this project.")

    now = _now()

    if hard_delete:
        # Hard delete: actually remove project + children rows
        # Must have an effect; if already absent we'd have returned NOT_FOUND earlier.
        projects.pop(idx)
        cols = [c for c in cols if not (isinstance(c, dict) and c.get("project_id") == project_id)]
        tasks = [t for t in tasks if not (isinstance(t, dict) and t.get("project_id") == project_id)]
        _save("projects.json", projects)
        _save("project_columns.json", cols)
        _save("tasks.json", tasks)
        _append_log(token_id, u.get("id"), "OK", None)
        return {"deleted": True, "hard_delete": True, "project_id": project_id}

    # Soft delete, idempotent
    if prj.get("status") == "deleted":
        _append_log(token_id, u.get("id"), "OK", None)
        return {"project": prj, "deleted": True, "hard_delete": False}

    # Lifecycle transition check active/archived -> deleted
    cur = prj.get("status")
    if cur not in ("active", "archived"):
        _append_log(token_id, u.get("id"), "INVALID_TRANSITION", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", f"Cannot transition project status from '{cur}' to 'deleted'.")

    prj2 = dict(prj)
    prj2["status"] = "deleted"
    prj2["deleted_at"] = _iso(now)
    prj2["updated_at"] = _iso(now)
    prj2["is_archived"] = True if prj2.get("is_archived") else prj2.get("is_archived", False)
    projects[idx] = prj2

    # Cascade: columns set deleted; tasks set deleted with deleted_at
    changed_cols = False
    for i, c in enumerate(cols):
        if not isinstance(c, dict):
            continue
        if c.get("project_id") != project_id:
            continue
        if c.get("status") != "deleted":
            c2 = dict(c)
            c2["status"] = "deleted"
            c2["updated_at"] = _iso(now)
            cols[i] = c2
            changed_cols = True

    changed_tasks = False
    for i, t in enumerate(tasks):
        if not isinstance(t, dict):
            continue
        if t.get("project_id") != project_id:
            continue
        if t.get("status") != "deleted":
            t2 = dict(t)
            t2["status"] = "deleted"
            t2["deleted_at"] = _iso(now)
            t2["updated_at"] = _iso(now)
            tasks[i] = t2
            changed_tasks = True

    _save("projects.json", projects)
    if changed_cols:
        _save("project_columns.json", cols)
    if changed_tasks:
        _save("tasks.json", tasks)

    # Update token last_used_at
    tokens = _load("api_tokens.json")
    if isinstance(tokens, list):
        for t in tokens:
            if isinstance(t, dict) and t.get("id") == token_id:
                t["last_used_at"] = _iso(now)
                t["updated_at"] = t.get("updated_at") or _iso(now)
                break
        _save("api_tokens.json", tokens)

    _append_log(token_id, u.get("id"), "OK", None)
    return {"project": prj2, "deleted": True, "hard_delete": False}

def get_task_by_ids(project_id, task_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0028000" if __import__("os").path.isdir("./environment_mix/0028000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(token_id, user_id_for_log, outcome, error_code=None):
        logs = _load_logs()
        logs.append({
            "id": "tt_req_" + _now().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_task_by_ids",
            "token_id": token_id,
            "user_id": user_id_for_log,
            "status": outcome,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(token_id, user_id_for_rl):
        logs = _load_logs()
        now = _now()
        minute_cutoff = now - datetime.timedelta(seconds=60)
        day_cutoff = now - datetime.timedelta(days=1)
        token_min = user_min = user_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("created_at"))
            if not isinstance(ts, datetime.datetime):
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= minute_cutoff:
                if token_id is not None and r.get("token_id") == token_id:
                    token_min += 1
                if user_id_for_rl is not None and r.get("user_id") == user_id_for_rl:
                    user_min += 1
            if ts >= day_cutoff and user_id_for_rl is not None and r.get("user_id") == user_id_for_rl:
                user_day += 1
        if token_id is not None and token_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for token (120/min).")
        if user_id_for_rl is not None and user_min >= 600:
            return _err("RATE_LIMIT", "Rate limit exceeded for user (600/min).")
        if user_id_for_rl is not None and user_day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for user (20k/day).")
        return None

    def _resolve_auth_user():
        tokens = _load("api_tokens.json")
        users = _load("users.json")
        if not isinstance(tokens, list):
            tokens = []
        if not isinstance(users, list):
            users = []
        users_by_id = {u.get("id"): u for u in users if isinstance(u, dict)}
        now = _now()
        for t in tokens:
            if not isinstance(t, dict):
                continue
            if t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at")) if t.get("expires_at") else None
            if isinstance(exp, datetime.datetime):
                if exp.tzinfo is None:
                    exp = exp.replace(tzinfo=datetime.timezone.utc)
                if exp <= now:
                    continue
            u = users_by_id.get(t.get("user_id"))
            if not isinstance(u, dict) or u.get("status") != "active":
                continue
            return t, u
        return None, None

    # Validate ids more permissively: accept datastore-style ids (tt_prj_..., tt_tsk_...) even if not 01H...
    if not isinstance(project_id, str) or not project_id.startswith("tt_prj_") or len(project_id) < 10:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
    if not isinstance(task_id, str) or not task_id.startswith("tt_tsk_") or len(task_id) < 10:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed task_id.", field="task_id")

    token, auth_user = _resolve_auth_user()
    if not token or not auth_user:
        _append_log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API token is missing/invalid.")

    rl_err = _rate_limit_check(token.get("id"), auth_user.get("id"))
    if rl_err:
        _append_log(token.get("id"), auth_user.get("id"), "error", rl_err["error"]["code"])
        return rl_err

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj or proj.get("status") == "deleted":
        _append_log(token.get("id"), auth_user.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", resource="projects", id=project_id)
    if proj.get("user_id") != auth_user.get("id"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to access this project.", rule="projects.user_id = current_user.id")

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    trow = next((t for t in tasks if isinstance(t, dict) and t.get("id") == task_id and t.get("project_id") == project_id), None)
    if not trow or trow.get("status") == "deleted":
        _append_log(token.get("id"), auth_user.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Task not found in project.", resource="tasks", id=task_id, project_id=project_id)

    # Token last_used_at update
    now_iso = _iso(_now())
    toks = _load("api_tokens.json")
    if isinstance(toks, list):
        changed = False
        for tr in toks:
            if isinstance(tr, dict) and tr.get("id") == token.get("id"):
                tr["last_used_at"] = now_iso
                changed = True
                break
        if changed:
            _save("api_tokens.json", toks)

    _append_log(token.get("id"), auth_user.get("id"), "success", None)
    return {"task": trow}

def create_task(project_id, user_id, title, column_id=None, content=None, priority=None, due_at=None, start_at=None, is_all_day=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0028000" if __import__("os").path.isdir("./environment_mix/0028000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _parse_rfc3339(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid date-time string", field=field)
        dt = _parse_dt(s)
        if not isinstance(dt, datetime.datetime):
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid date-time string", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _load_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(token_id, user_id_for_log, outcome, error_code=None):
        logs = _load_logs()
        logs.append({
            "id": "tt_req_" + _now().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "create_task",
            "token_id": token_id,
            "user_id": user_id_for_log,
            "status": outcome,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(token_id, user_id_for_rl):
        logs = _load_logs()
        now = _now()
        minute_cutoff = now - datetime.timedelta(seconds=60)
        day_cutoff = now - datetime.timedelta(days=1)
        token_min = user_min = user_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("created_at"))
            if not isinstance(ts, datetime.datetime):
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= minute_cutoff:
                if token_id is not None and r.get("token_id") == token_id:
                    token_min += 1
                if user_id_for_rl is not None and r.get("user_id") == user_id_for_rl:
                    user_min += 1
            if ts >= day_cutoff and user_id_for_rl is not None and r.get("user_id") == user_id_for_rl:
                user_day += 1
        if token_id is not None and token_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for token (120/min).")
        if user_id_for_rl is not None and user_min >= 600:
            return _err("RATE_LIMIT", "Rate limit exceeded for user (600/min).")
        if user_id_for_rl is not None and user_day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for user (20k/day).")
        return None

    def _resolve_auth_user():
        tokens = _load("api_tokens.json")
        users = _load("users.json")
        if not isinstance(tokens, list):
            tokens = []
        if not isinstance(users, list):
            users = []
        users_by_id = {u.get("id"): u for u in users if isinstance(u, dict)}
        now = _now()
        for t in tokens:
            if not isinstance(t, dict):
                continue
            if t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at")) if t.get("expires_at") else None
            if isinstance(exp, datetime.datetime):
                if exp.tzinfo is None:
                    exp = exp.replace(tzinfo=datetime.timezone.utc)
                if exp <= now:
                    continue
            u = users_by_id.get(t.get("user_id"))
            if not isinstance(u, dict) or u.get("status") != "active":
                continue
            return t, u
        return None, None

    # Validate inputs
    if not isinstance(project_id, str) or not project_id.startswith("tt_prj_") or len(project_id) < 10:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
    if not isinstance(user_id, str) or not user_id.startswith("tt_usr_") or len(user_id) < 10:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed user_id.", field="user_id")
    if column_id is not None and (not isinstance(column_id, str) or not column_id.startswith("tt_col_") or len(column_id) < 10):
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed column_id.", field="column_id")
