        if not isinstance(sort_order, int):
            token, u = _resolve_auth_user()
            _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort_order must be an integer", field="sort_order")
        if sort_order < 0:
            token, u = _resolve_auth_user()
            _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort_order must be >= 0", field="sort_order")

    due_dt, e = _parse_rfc3339(due_at, "due_at")
    if e:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", e["error"]["code"])
        return e
    start_dt, e = _parse_rfc3339(start_at, "start_at")
    if e:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", e["error"]["code"])
        return e
    if start_dt is not None and due_dt is not None and start_dt > due_dt:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_at must be <= due_at when both are set.", rule="start_at <= due_at when both are not null")

    token, auth_user = _resolve_auth_user()
    if not token or not auth_user:
        _append_log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API token is missing/invalid.")

    rl_err = _rate_limit_check(token.get("id"), auth_user.get("id"))
    if rl_err:
        _append_log(token.get("id"), auth_user.get("id"), "error", rl_err["error"]["code"])
        return rl_err

    if user_id != auth_user.get("id"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to create tasks for the specified user.", rule="tasks.user_id must equal current_user.id")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj or proj.get("status") == "deleted":
        _append_log(token.get("id"), auth_user.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", resource="projects", id=project_id)
    if proj.get("user_id") != auth_user.get("id"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to access this project.", rule="projects.user_id = current_user.id")

    # Cannot create/update tasks in deleted projects
    if proj.get("status") == "deleted":
        _append_log(token.get("id"), auth_user.get("id"), "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot create tasks in a deleted project.", rule="cannot create/update tasks in projects where projects.status='deleted'")

    # Kanban column validation
    if column_id is not None:
        if proj.get("view_mode") != "kanban":
            _append_log(token.get("id"), auth_user.get("id"), "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "column_id can only be set for kanban projects.", rule="project must have view_mode='kanban' to have active columns", field="column_id")
        cols = _load("project_columns.json")
        if not isinstance(cols, list):
            cols = []
        col = next((c for c in cols if isinstance(c, dict) and c.get("id") == column_id), None)
        if not col or col.get("status") != "active" or col.get("project_id") != project_id:
            _append_log(token.get("id"), auth_user.get("id"), "error", "NOT_FOUND")
            return _err("NOT_FOUND", "Column not found (must be active and belong to the same project).", resource="project_columns", id=column_id, rule="column_id must belong to same project_id when not null")

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    # Quota: at most 200000 non-deleted tasks
    non_deleted = 0
    for t in tasks:
        if isinstance(t, dict) and t.get("user_id") == auth_user.get("id") and t.get("status") != "deleted":
            non_deleted += 1
    if non_deleted >= 200000:
        _append_log(token.get("id"), auth_user.get("id"), "error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Task limit exceeded (max 200000 non-deleted tasks).", rule="at most 200000 non-deleted tasks")

    if sort_order is None:
        # Default sort order: append within project/column
        max_so = -1
        for t in tasks:
            if not isinstance(t, dict):
                continue
            if t.get("project_id") == project_id and t.get("status") != "deleted" and t.get("column_id") == column_id:
                so = t.get("sort_order")
                if isinstance(so, int) and so > max_so:
                    max_so = so
        sort_order_val = max_so + 1
    else:
        sort_order_val = sort_order

    now_iso = _iso(_now())
    new_id = "tt_tsk_" + secrets.token_hex(9).upper()
    rec = {
        "id": new_id,
        "project_id": project_id,
        "user_id": auth_user.get("id"),
        "column_id": column_id,
        "title": title.strip(),
        "content": content,
        "priority": int(priority) if priority is not None else 0,
        "due_at": _iso(due_dt) if due_dt is not None else None,
        "start_at": _iso(start_dt) if start_dt is not None else None,
        "completed_at": None,
        "status": "active",
        "is_all_day": bool(is_all_day) if is_all_day is not None else False,
        "sort_order": sort_order_val,
        "created_at": now_iso,
        "updated_at": now_iso,
        "deleted_at": None
    }

    # Enforce integrity: tasks.user_id must equal projects.user_id
    if rec["user_id"] != proj.get("user_id"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "CONFLICT")
        return _err("CONFLICT", "Task user_id must match project owner.", rule="user_id must equal (select user_id from projects where projects.id = project_id)")

    tasks.append(rec)
    _save("tasks.json", tasks)

    # Token last_used_at update
    toks = _load("api_tokens.json")
    if isinstance(toks, list):
        changed = False
        for tr in toks:
            if isinstance(tr, dict) and tr.get("id") == token.get("id"):
                tr["last_used_at"] = now_iso
                changed = True
                break
        if changed:
            _save("api_tokens.json", toks)

    _append_log(token.get("id"), auth_user.get("id"), "success", None)
    return {"task": rec}

def update_task(task_id, title=None, content=None, priority=None, due_at=None, start_at=None, is_all_day=None, project_id=None, column_id=None, sort_order=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0028000" if __import__("os").path.isdir("./environment_mix/0028000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _parse_rfc3339(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid date-time string", field=field)
        dt = _parse_dt(s)
        if not isinstance(dt, datetime.datetime):
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid date-time string", field=field)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _load_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(token_id, user_id_for_log, outcome, error_code=None):
        logs = _load_logs()
        logs.append({
            "id": "tt_req_" + _now().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "update_task",
            "token_id": token_id,
            "user_id": user_id_for_log,
            "status": outcome,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(token_id, user_id_for_rl):
        logs = _load_logs()
        now = _now()
        minute_cutoff = now - datetime.timedelta(seconds=60)
        day_cutoff = now - datetime.timedelta(days=1)
        token_min = user_min = user_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("created_at"))
            if not isinstance(ts, datetime.datetime):
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= minute_cutoff:
                if token_id is not None and r.get("token_id") == token_id:
                    token_min += 1
                if user_id_for_rl is not None and r.get("user_id") == user_id_for_rl:
                    user_min += 1
            if ts >= day_cutoff and user_id_for_rl is not None and r.get("user_id") == user_id_for_rl:
                user_day += 1
        if token_id is not None and token_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for token (120/min).")
        if user_id_for_rl is not None and user_min >= 600:
            return _err("RATE_LIMIT", "Rate limit exceeded for user (600/min).")
        if user_id_for_rl is not None and user_day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for user (20k/day).")
        return None

    def _resolve_auth_user():
        tokens = _load("api_tokens.json")
        users = _load("users.json")
        if not isinstance(tokens, list):
            tokens = []
        if not isinstance(users, list):
            users = []
        users_by_id = {u.get("id"): u for u in users if isinstance(u, dict)}
        now = _now()
        for t in tokens:
            if not isinstance(t, dict):
                continue
            if t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at")) if t.get("expires_at") else None
            if isinstance(exp, datetime.datetime):
                if exp.tzinfo is None:
                    exp = exp.replace(tzinfo=datetime.timezone.utc)
                if exp <= now:
                    continue
            u = users_by_id.get(t.get("user_id"))
            if not isinstance(u, dict) or u.get("status") != "active":
                continue
            return t, u
        return None, None

    # Validate id formats permissively
    if not isinstance(task_id, str) or not task_id.startswith("tt_tsk_") or len(task_id) < 10:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed task_id.", field="task_id")

    if title is not None and (not isinstance(title, str) or len(title.strip()) < 1):
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a non-empty string", field="title")
    if content is not None and not isinstance(content, str):
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "content must be a string", field="content")
    if priority is not None and (not isinstance(priority, int) or priority not in (0, 1, 3, 5)):
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "priority must be one of: 0, 1, 3, 5", field="priority")
    if is_all_day is not None and not isinstance(is_all_day, bool):
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_all_day must be a boolean", field="is_all_day")
    if sort_order is not None:
        if not isinstance(sort_order, int):
            token, u = _resolve_auth_user()
            _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort_order must be an integer", field="sort_order")
        if sort_order < 0:
            token, u = _resolve_auth_user()
            _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort_order must be >= 0", field="sort_order")

    if project_id is not None and (not isinstance(project_id, str) or not project_id.startswith("tt_prj_") or len(project_id) < 10):
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed project_id.", field="project_id")
    if column_id is not None and (not isinstance(column_id, str) or not column_id.startswith("tt_col_") or len(column_id) < 10):
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed column_id.", field="column_id")

    due_dt, e = _parse_rfc3339(due_at, "due_at")
    if e:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", e["error"]["code"])
        return e
    start_dt, e = _parse_rfc3339(start_at, "start_at")
    if e:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", e["error"]["code"])
        return e
    if start_dt is not None and due_dt is not None and start_dt > due_dt:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "start_at must be <= due_at when both are set.", rule="start_at <= due_at when both are not null")

    token, auth_user = _resolve_auth_user()
    if not token or not auth_user:
        _append_log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API token is missing/invalid.")

    rl_err = _rate_limit_check(token.get("id"), auth_user.get("id"))
    if rl_err:
        _append_log(token.get("id"), auth_user.get("id"), "error", rl_err["error"]["code"])
        return rl_err

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    idx = None
    existing = None
    for i, t in enumerate(tasks):
        if isinstance(t, dict) and t.get("id") == task_id:
            idx = i
            existing = t
            break
    if existing is None:
        _append_log(token.get("id"), auth_user.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Task not found.", resource="tasks", id=task_id)

    if existing.get("user_id") != auth_user.get("id"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to modify this task.", rule="tasks.user_id = current_user.id")

    if existing.get("status") == "deleted":
        _append_log(token.get("id"), auth_user.get("id"), "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot update a deleted task.", rule="cannot directly update a task with status='deleted'")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    projects_by_id = {p.get("id"): p for p in projects if isinstance(p, dict)}

    # Determine destination project
    dest_project_id = project_id if project_id is not None else existing.get("project_id")
    dest_project = projects_by_id.get(dest_project_id)
    if not isinstance(dest_project, dict) or dest_project.get("status") == "deleted":
        _append_log(token.get("id"), auth_user.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Destination project not found.", resource="projects", id=dest_project_id)
    if dest_project.get("user_id") != auth_user.get("id"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to access destination project.", rule="projects.user_id = current_user.id")
    if dest_project.get("status") == "deleted":
        _append_log(token.get("id"), auth_user.get("id"), "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot move/update tasks in a deleted project.", rule="cannot create/update tasks in projects where projects.status='deleted'")

    # Destination column validation
    dest_column_id = column_id if column_id is not None else existing.get("column_id")
    if dest_project.get("view_mode") != "kanban":
        # list project: force null column placement
        dest_column_id = None
    else:
        # kanban: if provided/non-null, must be active and belong to same project
        if dest_column_id is not None:
            cols = _load("project_columns.json")
            if not isinstance(cols, list):
                cols = []
            col = next((c for c in cols if isinstance(c, dict) and c.get("id") == dest_column_id), None)
            if not col or col.get("status") != "active" or col.get("project_id") != dest_project_id:
                _append_log(token.get("id"), auth_user.get("id"), "error", "NOT_FOUND")
                return _err("NOT_FOUND", "Column not found (must be active and belong to the same project).", resource="project_columns", id=dest_column_id, rule="column_id must belong to same project_id when not null")

    # Apply updates
    updated = dict(existing)
    if title is not None:
        updated["title"] = title.strip()
    if content is not None:
        updated["content"] = content
    if priority is not None:
        updated["priority"] = priority
    if due_at is not None:
        updated["due_at"] = _iso(due_dt) if due_dt is not None else None
    if start_at is not None:
        updated["start_at"] = _iso(start_dt) if start_dt is not None else None
    if is_all_day is not None:
        updated["is_all_day"] = is_all_day
    if sort_order is not None:
        updated["sort_order"] = sort_order

    updated["project_id"] = dest_project_id
    updated["column_id"] = dest_column_id

    # Enforce integrity constraint: user_id must match project owner
    if dest_project.get("user_id") != updated.get("user_id"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "CONFLICT")
        return _err("CONFLICT", "Task user_id must match project owner.", rule="user_id must equal (select user_id from projects where projects.id = project_id)")

    updated["updated_at"] = _iso(_now())

    # No success without effect: if nothing changed, still a valid call; return current row (idempotent-ish)
    if updated == existing:
        _append_log(token.get("id"), auth_user.get("id"), "success", None)
        return {"task": existing}

    tasks[idx] = updated
    _save("tasks.json", tasks)

    # token last_used_at
    toks = _load("api_tokens.json")
    if isinstance(toks, list):
        for tr in toks:
            if isinstance(tr, dict) and tr.get("id") == token.get("id"):
                tr["last_used_at"] = updated["updated_at"]
                break
        _save("api_tokens.json", toks)

    _append_log(token.get("id"), auth_user.get("id"), "success", None)
    return {"task": updated}

