            task = t
            break
    if task is None:
        _append_log(token.get("id"), auth_user.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Task not found.", resource="tasks", id=task_id)

    if task.get("user_id") != auth_user.get("id"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to modify this task.", rule="tasks.user_id = current_user.id")

    if task.get("status") == "deleted":
        _append_log(token.get("id"), auth_user.get("id"), "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot complete a deleted task.", rule="tasks lifecycle deleted -> []")

    # Validate project not deleted if attempting to complete
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == task.get("project_id")), None)
    if isinstance(proj, dict) and proj.get("status") == "deleted":
        _append_log(token.get("id"), auth_user.get("id"), "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot set status='completed' if project.status='deleted'.", rule="cannot set status='completed' if project.status='deleted'")

    # Idempotent: if already completed, return as-is (no-op)
    if task.get("status") == "completed":
        # still record last_used_at
        now_iso = _iso(_now())
        toks = _load("api_tokens.json")
        if isinstance(toks, list):
            for tr in toks:
                if isinstance(tr, dict) and tr.get("id") == token.get("id"):
                    tr["last_used_at"] = now_iso
                    break
            _save("api_tokens.json", toks)
        _append_log(token.get("id"), auth_user.get("id"), "success", None)
        return {"task": task}

    # Transition active -> completed
    now_iso = _iso(_now())
    task2 = dict(task)
    task2["status"] = "completed"
    task2["completed_at"] = _iso(comp_dt) if comp_dt is not None else now_iso
    task2["updated_at"] = now_iso
    task2["deleted_at"] = None

    tasks[idx] = task2
    _save("tasks.json", tasks)

    toks = _load("api_tokens.json")
    if isinstance(toks, list):
        for tr in toks:
            if isinstance(tr, dict) and tr.get("id") == token.get("id"):
                tr["last_used_at"] = now_iso
                break
        _save("api_tokens.json", toks)

    _append_log(token.get("id"), auth_user.get("id"), "success", None)
    return {"task": task2}

def delete_task(task_id, **_extra):
