                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if not isinstance(dt, datetime.datetime):
            dt = _now()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return None

    def _load_logs():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        return logs

    def _append_log(token_id, user_id_for_log, outcome, error_code=None):
        logs = _load_logs()
        logs.append({
            "id": "tt_req_" + _now().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "delete_task",
            "token_id": token_id,
            "user_id": user_id_for_log,
            "status": outcome,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _iso(_now()),
        })
        _save("request_logs.json", logs)

    def _rate_limit_check(token_id, user_id_for_rl):
        logs = _load_logs()
        now = _now()
        minute_cutoff = now - datetime.timedelta(seconds=60)
        day_cutoff = now - datetime.timedelta(days=1)
        token_min = user_min = user_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_dt(r.get("created_at"))
            if not isinstance(ts, datetime.datetime):
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts >= minute_cutoff:
                if token_id is not None and r.get("token_id") == token_id:
                    token_min += 1
                if user_id_for_rl is not None and r.get("user_id") == user_id_for_rl:
                    user_min += 1
            if ts >= day_cutoff and user_id_for_rl is not None and r.get("user_id") == user_id_for_rl:
                user_day += 1
        if token_id is not None and token_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded for token (120/min).")
        if user_id_for_rl is not None and user_min >= 600:
            return _err("RATE_LIMIT", "Rate limit exceeded for user (600/min).")
        if user_id_for_rl is not None and user_day >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for user (20k/day).")
        return None

    def _resolve_auth_user():
        tokens = _load("api_tokens.json")
        users = _load("users.json")
        if not isinstance(tokens, list):
            tokens = []
        if not isinstance(users, list):
            users = []
        users_by_id = {u.get("id"): u for u in users if isinstance(u, dict)}
        now = _now()
        for t in tokens:
            if not isinstance(t, dict):
                continue
            if t.get("status") != "active":
                continue
            exp = _parse_dt(t.get("expires_at")) if t.get("expires_at") else None
            if isinstance(exp, datetime.datetime):
                if exp.tzinfo is None:
                    exp = exp.replace(tzinfo=datetime.timezone.utc)
                if exp <= now:
                    continue
            u = users_by_id.get(t.get("user_id"))
            if not isinstance(u, dict) or u.get("status") != "active":
                continue
            return t, u
        return None, None

    if not isinstance(task_id, str) or not task_id.startswith("tt_tsk_") or len(task_id) < 10:
        token, u = _resolve_auth_user()
        _append_log(token.get("id") if token else None, u.get("id") if u else None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed task_id.", field="task_id")

    token, auth_user = _resolve_auth_user()
    if not token or not auth_user:
        _append_log(None, None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API token is missing/invalid.")

    rl_err = _rate_limit_check(token.get("id"), auth_user.get("id"))
    if rl_err:
        _append_log(token.get("id"), auth_user.get("id"), "error", rl_err["error"]["code"])
        return rl_err

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    idx = None
    task = None
    for i, t in enumerate(tasks):
        if isinstance(t, dict) and t.get("id") == task_id:
            idx = i
            task = t
            break
    if task is None:
        _append_log(token.get("id"), auth_user.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Task not found.", resource="tasks", id=task_id)

    if task.get("user_id") != auth_user.get("id"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to delete this task.", rule="tasks.user_id = current_user.id")

    # Idempotent: if already deleted, return success confirmation
    now_iso = _iso(_now())
    if task.get("status") == "deleted":
        toks = _load("api_tokens.json")
        if isinstance(toks, list):
            for tr in toks:
                if isinstance(tr, dict) and tr.get("id") == token.get("id"):
                    tr["last_used_at"] = now_iso
                    break
            _save("api_tokens.json", toks)
        _append_log(token.get("id"), auth_user.get("id"), "success", None)
        return {"deleted": True, "task_id": task_id}

    task2 = dict(task)
    task2["status"] = "deleted"
    task2["deleted_at"] = now_iso
    task2["completed_at"] = None  # keep invariant: completed_at is not null iff completed
    task2["updated_at"] = now_iso
    tasks[idx] = task2
    _save("tasks.json", tasks)

    toks = _load("api_tokens.json")
    if isinstance(toks, list):
        for tr in toks:
            if isinstance(tr, dict) and tr.get("id") == token.get("id"):
                tr["last_used_at"] = now_iso
                break
        _save("api_tokens.json", toks)

    _append_log(token.get("id"), auth_user.get("id"), "success", None)
    return {"deleted": True, "task_id": task_id}

def get_current_user(include_rate_limits=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0028000" if __import__("os").path.isdir("./environment_mix/0028000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be a RFC 3339 date-time string")
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid RFC 3339 date-time")

    def _log(status, token_id=None, user_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"tt_req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": "get_current_user",
            "token_id": token_id,
            "user_id": user_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _iso(_now()),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _auth():
        tokens = _load("api_tokens.json")
        users = _load("users.json")
        if not isinstance(tokens, list): tokens = []
        if not isinstance(users, list): users = []
        now = _now()
        for tok in tokens:
            try:
                if tok.get("provider") != "ticktick":
                    continue
                if tok.get("status") != "active":
                    continue
                exp = tok.get("expires_at")
                if exp:
                    dt, perr = _parse_rfc3339(exp, "expires_at")
                    if perr:
                        continue
                    if dt <= now:
                        continue
                uid = tok.get("user_id")
                u = next((x for x in users if x.get("id") == uid), None)
                if not u or u.get("status") == "deleted":
                    continue
                return u, tok
            except Exception:
                continue
        return None, None

    def _rate_limit_snapshot(token_id, user_id):
        limits = _load("rate_limits.json")
        if not isinstance(limits, dict):
            return None
        per_min = limits.get("per_minute")
        per_day = limits.get("per_day")
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        one_min_ago = now - datetime.timedelta(minutes=1)
        day_ago = now - datetime.timedelta(days=1)

        def _ts(row):
            dt, perr = _parse_rfc3339(row.get("created_at"), "created_at")
            if perr:
                return None
            return dt

        relevant = [r for r in logs if (r.get("token_id") == token_id or r.get("user_id") == user_id)]
        used_min = 0
        used_day = 0
        for r in relevant:
            dt = _ts(r)
            if not dt:
                continue
            if dt >= one_min_ago:
                used_min += 1
            if dt >= day_ago:
                used_day += 1
        snap = {"used": {}, "limit": {}}
        if per_min is not None:
            snap["used"]["per_minute"] = used_min
            snap["limit"]["per_minute"] = int(per_min)
        if per_day is not None:
            snap["used"]["per_day"] = used_day
            snap["limit"]["per_day"] = int(per_day)
        return snap

    def _rate_limit_check(token_id, user_id):
        snap = _rate_limit_snapshot(token_id, user_id)
        if not snap:
            return None
        lim = snap.get("limit", {})
        used = snap.get("used", {})
        if "per_minute" in lim and used.get("per_minute", 0) >= lim["per_minute"]:
            return _err("RATE_LIMIT", "Rate limit exceeded", rate_limits=snap)
        if "per_day" in lim and used.get("per_day", 0) >= lim["per_day"]:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", rate_limits=snap)
        return None

    if include_rate_limits is not None and not isinstance(include_rate_limits, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_rate_limits must be a boolean")

    user, tok = _auth()
    if not user or not tok:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API token missing/invalid/expired/revoked")

    rl = _rate_limit_check(tok.get("id"), user.get("id"))
    if rl:
        _log("error", token_id=tok.get("id"), user_id=user.get("id"), error_code=rl["error"]["code"])
        return rl

    now_iso = _iso(_now())
    tok["last_used_at"] = now_iso
    tok["updated_at"] = now_iso
    tokens = _load("api_tokens.json")
    if not isinstance(tokens, list): tokens = []
    for i, x in enumerate(tokens):
        if x.get("id") == tok.get("id"):
            tokens[i] = tok
            break
    _save("api_tokens.json", tokens)

    resp = {
        "user": user,
        "token": {
            "id": tok.get("id"),
            "provider": tok.get("provider"),
            "status": tok.get("status"),
            "scopes": tok.get("scopes") if isinstance(tok.get("scopes"), list) else [],
            "expires_at": tok.get("expires_at"),
            "last_used_at": tok.get("last_used_at"),
        }
    }
    if include_rate_limits:
        snap = _rate_limit_snapshot(tok.get("id"), user.get("id"))
        if snap:
            resp["rate_limits"] = snap

    _log("ok", token_id=tok.get("id"), user_id=user.get("id"))
    return resp

