    if not proj or proj.get("status") == "deleted":
        _append_log(token.get("id"), auth_user.get("id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", resource="projects", id=project_id)
    if proj.get("user_id") != auth_user.get("id"):
        _append_log(token.get("id"), auth_user.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Token is not allowed to access this project.", rule="projects.user_id = current_user.id")

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    rows = []
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("project_id") != project_id:
            continue
        if status is not None and t.get("status") != status:
            continue
        if column_id is not None and t.get("column_id") != column_id:
            continue
        rows.append(t)

    # Sorting
    def _key(r):
        v = r.get(sort_by_val)
        if sort_by_val in ("due_at", "start_at", "created_at", "updated_at"):
            dt = _parse_dt(v) if isinstance(v, str) else None
            if isinstance(dt, datetime.datetime):
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.timestamp()
            return float("-inf") if sort_dir_val == "asc" else float("inf")
        if isinstance(v, int):
            return v
        return 0

    reverse = (sort_dir_val == "desc")
    rows.sort(key=_key, reverse=reverse)

    # Cursor: opaque, but accept any string; treat as "start after task id"
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _append_log(token.get("id"), auth_user.get("id"), "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                start = i + 1
                break

    page = rows[start:start + limit_val]
    has_more = start + limit_val < len(rows)
    next_cursor = page[-1].get("id") if has_more and page else None

    # token last_used_at
    now_iso = _iso(_now())
    toks = _load("api_tokens.json")
    if isinstance(toks, list):
        for tr in toks:
            if isinstance(tr, dict) and tr.get("id") == token.get("id"):
                tr["last_used_at"] = now_iso
                break
        _save("api_tokens.json", toks)

    _append_log(token.get("id"), auth_user.get("id"), "success", None)
    return {
        "tasks": page,
        "total": len(rows),
        "limit": limit_val,
        "has_more": has_more,
        "next_cursor": next_cursor
    }
